GENERIC_STARTS = [
    'در پروژه‌های حساس، بهتر است پس از نصب و راه‌اندازی، بازخورد واقعی بهره‌بردار',
    'در پروژه‌های حساس، قبل از خرید باید مشخص شود برند مورد نظر در Vendor List',
    'برای خرید برندمحور، بهتر است فروشنده تصویر پلاک، دیتاشیت رسمی، شرایط گارانتی',
]
DUP_TEXTS = [
    'در ارزیابی نهایی، پیشنهادها باید با جدول TBE مقایسه شوند. استاندارد، متریال، برند، مدارک، زمان تحویل، انحراف‌های فنی، اقلام جانبی و خدمات پس از فروش باید هم‌زمان دیده شوند.',
    'برای جمع‌بندی، خرید برندمحور زمانی مطمئن است که نام برند، مدل دقیق، مدارک، کشور ساخت، سازگاری فنی و تایید کارفرما هم‌زمان بررسی شود. اتکا به نام برند بدون کنترل مدارک و Model Code، ریسک مغایرت فنی و تأخیر پروژه را بالا می‌برد.',
    'در پروژه‌های وندورلیست‌دار، نام برند کافی نیست. مدل دقیق، Revision، مدارک، کشور ساخت و تطبیق با دیتاشیت باید کنترل شود. اگر کالا جایگزین مدل قدیمی است، ابعاد، پروتکل، Function و مدارک باید قبل از خرید تایید شود.',
]

def visible(s):
    return re.sub(r'\s+',' ', re.sub(r'<[^>]+>',' ',s)).strip()

def clean(html):
    def repl(m):
        t=visible(m.group(1))
        if any(t.startswith(x) for x in GENERIC_STARTS) or t in DUP_TEXTS:
            return ''
        return m.group(0)
    return re.sub(r'<p\b[^>]*>([\s\S]*?)</p>', repl, html)

